def read_ints():
    return list(map(int, input().split()))

def is_latin_square(matrix):
    n = len(matrix)
    for i in range(n):
        seen = [False] * (n + 1)
        for j in range(n):
            if seen[matrix[i][j]]:
                return False
            seen[matrix[i][j]] = True
    for j in range(n):
        seen = [False] * (n + 1)
        for i in range(n):
            if seen[matrix[i][j]]:
                return False
            seen[matrix[i][j]]= True
    return True

def find_good_subset(n, arrays):
    for subset in range(1, 1 << (2 * n)):
        subset = [(i + 1) for i in range(2 * n) if (subset & (1 << i))]
        if len(subset) != n:
            continue
        matrix = [arrays[i - 1] for i in subset]
        if is_latin_square(matrix):
            return subset
    return None

def main():
    t = int(input())
    results = []
    for _ in range(t):
        n = int(input())
        arrays = [read_ints() for _ in range(2 * n)]
        good_subset = find_good_subset(n, arrays)
        if good_subset:
            results.append((1, good_subset))
        else:
            results.append((0, []))

    for count, subset in results:
        print(count)
        print(*subset)

if __name__ == "__main__":
    main()
```

